const shopCopy={uk:{cart:'Кошик',favorites:'Обране',add:'У кошик',added:'Додано до кошика',empty:'Тут поки порожньо',remove:'Видалити',total:'Разом',less:'Зменшити кількість',more:'Збільшити кількість',saved:'Зберегти в обране',unsave:'Прибрати з обраного',limit:'У кошику вже вся доступна кількість',note:'Онлайн-оформлення замовлення ще не підключено.'},ru:{cart:'Корзина',favorites:'Избранное',add:'В корзину',added:'Добавлено в корзину',empty:'Здесь пока пусто',remove:'Удалить',total:'Итого',less:'Уменьшить количество',more:'Увеличить количество',saved:'Сохранить в избранное',unsave:'Убрать из избранного',limit:'В корзине уже всё доступное количество',note:'Онлайн-оформление заказа ещё не подключено.'},en:{cart:'Cart',favorites:'Favourites',add:'Add to cart',added:'Added to cart',empty:'Nothing here yet',remove:'Remove',total:'Total',less:'Decrease quantity',more:'Increase quantity',saved:'Save favourite',unsave:'Remove favourite',limit:'All available stock is already in your cart',note:'Online checkout is not connected yet.'}};
let favorites=[],cart=[],shopMode='cart';try{favorites=JSON.parse(localStorage.getItem('kari-favorites')||'[]');cart=JSON.parse(localStorage.getItem('kari-cart')||'[]');if(!Array.isArray(favorites))favorites=[];if(!Array.isArray(cart))cart=[]}catch{favorites=[];cart=[]}
const heart='<svg viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/></svg>';
function favoriteButton(p){const yes=favorites.includes(p.id);return `<button class="favorite-button ${yes?'is-saved':''}" data-favorite="${p.id}" aria-pressed="${yes}" aria-label="${shopCopy[lang][yes?'unsave':'saved']}: ${escapeHTML(p[lang])}">${heart}</button>`}
function persistShop(){try{localStorage.setItem('kari-cart',JSON.stringify(cart));localStorage.setItem('kari-favorites',JSON.stringify(favorites))}catch{}renderShop()}
function toast(message){$('#shop-toast').textContent=message;$('#shop-toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#shop-toast').classList.remove('visible'),2200)}
function renderShop(){const c=shopCopy[lang];$('#open-cart').setAttribute('aria-label',c.cart);$('#open-favorites').setAttribute('aria-label',c.favorites);$('#cart-count').textContent=cart.reduce((n,x)=>n+x.qty,0)||'';$('#favorite-count').textContent=favorites.length||'';$('#shop-title').textContent=c[shopMode];let total=0;const list=shopMode==='favorites'?products.filter(p=>favorites.includes(p.id)).map(p=>`<div class="saved-row"><button data-open-product="${p.id}"><img src="${p.image}" alt=""><span>${escapeHTML(p[lang])}<small>${price(p)}</small></span></button>${favoriteButton(p)}</div>`):cart.map((x,index)=>{const p=products.find(p=>p.id===x.product),v=p?.variants.find(v=>v.id===x.variant);if(!v)return '';total+=v.price*x.qty;return `<div class="cart-row"><img src="${p.image}" alt=""><div><button class="cart-product-name" data-open-product="${p.id}">${escapeHTML(p[lang])}</button><small>${escapeHTML(v[lang])}${x.pillow?' · '+escapeHTML(x.pillow):''}</small><strong>${money(v.price*x.qty)}</strong><div class="quantity"><button data-quantity="${index}" data-delta="-1" aria-label="${c.less}" ${x.qty<=1?'disabled':''}>−</button><span>${x.qty}</span><button data-quantity="${index}" data-delta="1" aria-label="${c.more}" ${x.qty>=v.stock?'disabled':''}>+</button><button class="remove-item" data-remove="${index}">${c.remove}</button></div></div></div>`});$('#shop-content').innerHTML=list.length?list.join(''):`<p class="shop-empty">${c.empty}</p>`;$('#shop-total').innerHTML=shopMode==='cart'&&list.length?`<div><span>${c.total}</span><strong>${money(total)}</strong></div><p>${c.note}</p>`:''}
function openShop(mode){shopMode=mode;renderShop();$('#shop-dialog').showModal()}
document.addEventListener('click',e=>{const f=e.target.closest('[data-favorite]');if(f){const id=f.dataset.favorite;favorites=favorites.includes(id)?favorites.filter(x=>x!==id):[...favorites,id];persistShop();document.querySelectorAll('[data-favorite]').forEach(b=>{const yes=favorites.includes(b.dataset.favorite);b.classList.toggle('is-saved',yes);b.setAttribute('aria-pressed',yes);const p=products.find(p=>p.id===b.dataset.favorite);b.setAttribute('aria-label',shopCopy[lang][yes?'unsave':'saved']+': '+p[lang])});return}if(e.target.closest('[data-add-cart]')){const p=activeProduct,v=p.variants.find(v=>v.id===selectedVariant),pillow=$('.pillow-label select')?.value||'',existing=cart.find(x=>x.product===p.id&&x.variant===v.id&&x.pillow===pillow),used=cart.filter(x=>x.variant===v.id).reduce((n,x)=>n+x.qty,0);if(used>=v.stock)return toast(shopCopy[lang].limit);if(existing)existing.qty++;else cart.push({product:p.id,variant:v.id,pillow,qty:1});persistShop();toast(shopCopy[lang].added)}const q=e.target.closest('[data-quantity]');if(q){const x=cart[+q.dataset.quantity],p=products.find(p=>p.id===x.product),v=p.variants.find(v=>v.id===x.variant),used=cart.filter(y=>y.variant===x.variant).reduce((n,y)=>n+y.qty,0),delta=+q.dataset.delta;if(delta>0&&used>=v.stock)return toast(shopCopy[lang].limit);x.qty=Math.max(1,x.qty+delta);persistShop()}const rm=e.target.closest('[data-remove]');if(rm){cart.splice(+rm.dataset.remove,1);persistShop()}const op=e.target.closest('[data-open-product]');if(op){openProduct(op.dataset.openProduct)}});
$('#open-cart').addEventListener('click',()=>openShop('cart'));$('#open-favorites').addEventListener('click',()=>openShop('favorites'));$('#close-shop').addEventListener('click',()=>$('#shop-dialog').close());$('#shop-dialog').addEventListener('click',e=>{if(e.target===$('#shop-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
