const fabricGuides={"gold": [["Бязь Голд люкс", "Тканина Gold Lux із полотняним переплетенням. Для комплектів «Класик» магазин указує щільність 125 ± 5 г/м².", "Для щоденного використання. Звірте розмір підковдри та наволочок перед вибором комплекту."], ["Бязь Голд люкс", "Ткань Gold Lux с полотняным переплетением. Для комплектов «Классик» магазин указывает плотность 125 ± 5 г/м².", "Для ежедневного использования. Сверьте размер пододеяльника и наволочек перед выбором комплекта."], ["Gold Lux calico", "Gold Lux fabric with a plain weave. Kari-San lists 125 ± 5 g/m² for Classic sets.", "An everyday bedding option. Check duvet-cover and pillowcase dimensions before choosing a set."]], "satin": [["Сатин", "Сатинове переплетення створює гладку поверхню. Назва переплетення сама по собі не визначає склад волокон.", "Обирайте, якщо подобається гладка фактура. Відсотковий склад і щільність для цих моделей на сайті магазину не вказані."], ["Сатин", "Сатиновое переплетение создаёт гладкую поверхность. Название переплетения само по себе не определяет состав волокон.", "Выбирайте, если нравится гладкая фактура. Процентный состав и плотность этих моделей на сайте магазина не указаны."], ["Satin", "Satin weave creates a smooth surface. The weave name alone does not establish fibre composition.", "Choose for a smooth texture. The store does not specify fibre percentages or fabric weight for these models."]], "stripe": [["Страйп сатин", "Сатин зі смугастим візерунком, утвореним чергуванням переплетень.", "Для стриманого оформлення спальні. Точний склад і щільність перевіряйте за етикеткою: у джерелі вони не вказані."], ["Страйп сатин", "Сатин с полосатым узором, образованным чередованием переплетений.", "Для сдержанного оформления спальни. Точный состав и плотность проверяйте по этикетке: в источнике они не указаны."], ["Stripe satin", "Satin with a striped pattern formed by alternating weave structures.", "For a restrained bedroom look. Check the label for exact composition and weight, which the source does not specify."]], "washed": [["Варена бавовна", "У каталозі Kari-San ця лінійка представлена як «Варена бавовна». У картках указані розміри складових комплекту.", "Спочатку звірте розміри ковдри та подушок. Не переносіть розміри з одного варіанта комплекту на інший."], ["Варёный хлопок", "В каталоге Kari-San эта линейка представлена как «Варёный хлопок». В карточках указаны размеры составляющих комплекта.", "Сначала сверьте размеры одеяла и подушек. Не переносите размеры с одного варианта комплекта на другой."], ["Washed cotton", "Kari-San lists this range as washed cotton. Product descriptions specify bedding dimensions.", "Check your duvet and pillows first. Dimensions listed for one set size do not apply automatically to other variants."]], "flannel": [["Байка", "Байка — тканина з м’яким ворсом. Конкретних товарів і підтвердженого складу в цьому розділі поки немає.", "Перед покупкою перевірте склад, щільність і догляд на етикетці конкретного виробу."], ["Байка", "Байка — ткань с мягким ворсом. Конкретных товаров и подтверждённого состава в этом разделе пока нет.", "Перед покупкой проверьте состав, плотность и уход на этикетке конкретного изделия."], ["Flannel", "A fabric with a soft raised surface. No products or confirmed compositions are currently listed in this section.", "Check the individual product label for composition, fabric weight and care."]]};
function fabricAdvice(cat){const g=fabricGuides[cat]?.[{uk:0,ru:1,en:2}[lang]];if(!g)return '';return `<div class="fabric-guide"><h3>${g[0]}</h3><p>${g[1]}</p><p><strong>${{uk:'Як обрати',ru:'Как выбрать',en:'Choosing your fabric'}[lang]}:</strong> ${g[2]}</p><p class="fabric-care">${{uk:'Догляд: дотримуйтеся етикетки конкретного виробу; не застосовуйте однаковий режим прання до всіх тканин.',ru:'Уход: следуйте этикетке конкретного изделия; не используйте один режим стирки для всех тканей.',en:'Care: follow the individual product label; do not use one washing programme for every fabric.'}[lang]}</p></div>`}
function collectionNavigation(){const c=collectionCopy[lang];$('.catalog-heading h2').textContent=c.title;$('.catalog-heading>p').textContent=c.intro;const ids=['bedding','pillows','duvets','towels','covers','protectors'];$('#collection-categories').innerHTML=ids.map(id=>`<a href="#catalog/${id}" class="collection-tile ${category===id||(id==='bedding'&&subs.includes(category))?'active':''}" ${category===id?'aria-current="page"':''}>${categoryIcon(id)}<span>${name(id)}</span></a>`).join('');$('#fabric-options').innerHTML=(category==='bedding'||subs.includes(category))?['bedding',...subs].map(id=>`<a href="#catalog/${id}" class="${id===category?'active':''}">${id==='bedding'?c.all:name(id)}</a>`).join(''):'';$('#category-description').textContent=c[subs.includes(category)?'bedding':category]||c.generic;$('#category-fabric-guide').innerHTML=fabricAdvice(category)}
function renderProducts(){ catalogControls();collectionNavigation();$('#category-list').innerHTML=links();$('#menu-categories').innerHTML=links();$('#category-title').textContent=name(category);const c=catalogCopy[lang];const list=products.filter(matching).filter(p=>!catalogQuery||p[lang].toLocaleLowerCase().includes(catalogQuery));if(catalogSort!=='default')list.sort((a,b)=>catalogSort==='low'?a.price-b.price:b.price-a.price);$('#result-count').textContent=`${c.found}: ${list.length}`;$('#products').innerHTML=loadFailed?`<div class="empty">${text[lang].loadError} <button id="retry-products">${text[lang].retry}</button></div>`:list.length?list.map(p=>`<article class="product">${favoriteButton(p)}<button data-product="${p.id}" aria-label="${escapeHTML(p[lang])}"><div class="product-image"><img loading="lazy" width="800" height="800" src="${p.image}" alt="${escapeHTML(p[lang])}">${p.new?`<span class="product-tag">${text[lang].new}</span>`:''}</div><span class="product-category">${name(p.category)}</span><h4>${escapeHTML(p[lang])}</h4><span class="price">${price(p)}</span><span class="product-stock ${p.variants.some(v=>v.stock>0)?'in-stock':'out-stock'}">${p.variants.some(v=>v.stock>0)?c.available:c.unavailable}</span></button></article>`).join(''):`<div class="empty">${catalogQuery?`${c.none}<br><button id="clear-catalog-search">${c.clear}</button>`:text[lang].empty}</div>`;$('#clear-catalog-search')?.addEventListener('click',()=>{catalogQuery='';$('#catalog-search').value='';renderProducts();$('#catalog-search').focus()});$('#retry-products')?.addEventListener('click',loadProducts)}
const productCopy={uk:{size:'Розмір',stock:'На складі',price:'Ціна',material:'Матеріал',pcs:'шт.',none:'Немає в наявності',pillow:'Розмір наволочок',sku:'Артикул'},ru:{size:'Размер',stock:'На складе',price:'Цена',material:'Материал',pcs:'шт.',none:'Нет в наличии',pillow:'Размер наволочек',sku:'Артикул'},en:{size:'Size',stock:'In stock',price:'Price',material:'Material',pcs:'pcs',none:'Out of stock',pillow:'Pillowcase size',sku:'SKU'}};
let selectedVariant=null;
function money(n){return new Intl.NumberFormat(lang==='uk'?'uk-UA':lang==='ru'?'ru-RU':'en-GB').format(n)+' ₴'}
function detail(p){const keep=activeProduct?.id===p.id;activeProduct=p;if(!keep||!p.variants.some(v=>v.id===selectedVariant))selectedVariant=(p.variants.find(v=>v.stock>0)||p.variants[0]).id;const v=p.variants.find(v=>v.id===selectedVariant),c=productCopy[lang];$('#product-detail').innerHTML=`<div class="detail-photo"><img src="${p.image}" alt="${escapeHTML(p[lang])}"></div><div class="detail-info"><p class="eyebrow">${name(p.category)}</p><h1 id="product-title">${escapeHTML(p[lang])}</h1><p class="detail-price">${money(v.price)}</p><p class="stock-summary ${v.stock>0?'in-stock':'out-stock'}">${v.stock>0?`${c.stock}: ${v.stock} ${c.pcs}`:c.none}</p><fieldset class="variant-list"><legend>${c.size}</legend><div class="variant-head"><span>${c.size}</span><span>${c.stock}</span><span>${c.price}</span></div>${p.variants.map(x=>`<label class="variant ${x.id===v.id?'selected':''}"><input type="radio" name="product-variant" value="${x.id}" ${x.id===v.id?'checked':''}><span>${escapeHTML(x[lang])}<small>${escapeHTML(x.sku)}</small></span><span class="variant-stock ${x.stock>0?'in-stock':'out-stock'}"><span>${x.stock>0?catalogCopy[lang].available:c.none}</span><small>${x.stock??'—'} ${c.pcs}</small></span><strong>${money(x.price)}</strong></label>`).join('')}</fieldset>${v.pillowSizes.length?`<label class="pillow-label">${c.pillow}<select>${v.pillowSizes.map(size=>`<option>${escapeHTML(size)}</option>`).join('')}</select></label>`:''}<div class="purchase-actions"><button class="pill add-cart" data-add-cart ${v.stock>0?'':'disabled'}>${shopCopy[lang].add}</button>${favoriteButton(p)}</div><details class="product-description" open><summary>${collectionCopy[lang].composition}</summary><p>${escapeHTML(p.material[lang])}</p>${fabricAdvice(p.category)}</details><details class="product-description" open><summary>${collectionCopy[lang].specs}</summary><dl><div><dt>${collectionCopy[lang].sku}</dt><dd>${escapeHTML(v.sku||v.id)}</dd></div><div><dt>${collectionCopy[lang].selected}</dt><dd>${escapeHTML(v[lang])}</dd></div><div><dt>${c.stock}</dt><dd class="${v.stock>0?'in-stock':'out-stock'}">${v.stock??'—'} ${c.pcs}</dd></div></dl></details></div>`;$('#product-dialog').setAttribute('aria-labelledby','product-title')}
$('#product-detail').addEventListener('change',e=>{if(e.target.name==='product-variant'){selectedVariant=e.target.value;detail(activeProduct);$('#product-detail input:checked')?.focus({preventScroll:true})}});
function setScene(t,force=false){let i=0;scenes.forEach((s,k)=>{if(t>=s.time)i=k});if(i===sceneIndex&&!force)return;sceneIndex=i;const s=scenes[i],a=s[lang];$('#scene-kicker').textContent=a[0];$('#scene-title').innerHTML=i?name(s.cat):a[1];$('#scene-description').textContent=i===1?({uk:'Бязь Голд люкс · Страйп сатин · Сатин · Варена бавовна · Байка',ru:'Бязь Голд люкс · Страйп сатин · Сатин · Варёный хлопок · Байка',en:'Gold Lux calico · Stripe satin · Satin · Washed cotton · Flannel'}[lang]):a[2];if(!reduced&&!force)$('.story-copy').animate([{opacity:0,transform:'translateY(10px)'},{opacity:1,transform:'translateY(0)'}],{duration:650,easing:'ease-out'});$('#scene-link').href=`#catalog/${s.cat}`;$('#scene-count').textContent=String(Math.min(i+1,7)).padStart(2,'0')+' / 07';$('#scene-name').textContent=i?name(s.cat).toUpperCase():'KARI-SAN';$$('#chapters button').forEach((b,k)=>b.classList.toggle('active',k===(i===7?2:i)))}
function translate(){$('#current-language').textContent=lang==='uk'?'UA':lang.toUpperCase();document.documentElement.lang=lang;$$('[data-t]').forEach(el=>el.innerHTML=text[lang][el.dataset.t]);$$('[data-lang]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.lang===lang)));$('#menu-button').setAttribute('aria-label',text[lang].menu);$('#close-menu').setAttribute('aria-label',text[lang].close);$('.close-product').setAttribute('aria-label',text[lang].close);$('#category-list').setAttribute('aria-label',text[lang].catalog);$('#chapters').innerHTML=scenes.slice(0,7).map((s,i)=>`<button data-scene="${i}" aria-label="${i?name(s.cat):'Kari-San'}">${String(i+1).padStart(2,'0')}</button>`).join('');renderProducts();renderShop();setScene(renderedStoryTime,true);if(activeProduct)detail(activeProduct);if(isProductPage)$$('a[href^="#"]').forEach(a=>a.setAttribute('href','index.html'+a.getAttribute('href')))}
const video=$('#hero'),story=$('.story'),mobileQuery=matchMedia('(max-width:700px)'),motionQuery=matchMedia('(prefers-reduced-motion: reduce)');
let reduced=motionQuery.matches,player=null,renderedStoryTime=0;
const timeline=[[0,0],[.045,0],[.17,3.25],[.185,4.65],[.29,6.65],[.30,7.65],[.42,10.2],[.435,11.1],[.55,13.7],[.565,14.65],[.68,17.2],[.695,18.45],[.81,20.45],[.825,21.45],[.95,24.65],[1,25]];
function unusedFrameComposition(t){const points=[[0,56],[3.9,56],[5,94],[6.7,94],[8,65],[10.5,65],[11.8,35],[13.8,35],[15,57],[17.5,57],[18.8,54],[20.8,54],[22,94],[24.1,94],[25,56]];let x=56;for(let i=1;i<points.length;i++){if(t<=points[i][0]){const [a,ax]=points[i-1],[b,bx]=points[i];const q=Math.max(0,Math.min(1,(t-a)/(b-a)));const smooth=q*q*(3-2*q);x=ax+(bx-ax)*smooth;break}}story.style.setProperty('--subject-x',x+'%')}
function timeFromProgress(p){return p*20.8}
function progressFromTime(t){return Math.min(1,t/20.8)}
function getProgress(){if(reduced)return 0;return Math.max(0,Math.min(1,-story.getBoundingClientRect().top/Math.max(1,story.offsetHeight-innerHeight)))}
function update(){const p=getProgress();$('#progress').style.width=`${p*100}%`;story.dataset.phase=p<.075?'opening':p>.93?'final':'motion';if(player)player.seek(timeFromProgress(p))}
const loadText={uk:'Завантаження відео…',ru:'Загрузка видео…',en:'Loading video…'};
function mediaState(state){$('#video-loading').hidden=state!=='loading';$('#video-loading').textContent=loadText[lang];$('#video-error').hidden=state!=='error';$('#retry-video').hidden=state!=='error';story.dataset.mediaState=state}
function initMedia(){player?.destroy();player=null;reduced=motionQuery.matches;document.documentElement.classList.toggle('reduced-motion',reduced);mediaState('ready');if(reduced){renderedStoryTime=0;setScene(0,true);story.dataset.phase='opening';return}player=new StoryPlayer({videos:[video,$('#hero-next')],onFrame:t=>{renderedStoryTime=t;story.dataset.frameTime=t.toFixed(3);setScene(t)},onState:mediaState});player.start();update()}
$('#retry-video').addEventListener('click',()=>player?.retry());
addEventListener('scroll',update,{passive:true});addEventListener('resize',update);motionQuery.addEventListener('change',initMedia);
$('#chapters').addEventListener('click',e=>{const b=e.target.closest('[data-scene]');if(!b)return;const s=scenes[Number(b.dataset.scene)];window.scrollTo({top:story.offsetTop+progressFromTime(s.time+(s.time?1:0))*(story.offsetHeight-innerHeight),behavior:reduced?'instant':'smooth'})});
